-- PostgreSQL schema for scbatchflow results.
-- Generated by `scbf db-schema`; edit src/scbatchflow/db.py, not this file.

CREATE TABLE run (
	run_id VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	pipeline_version VARCHAR(32) NOT NULL, 
	final_method VARCHAR(32), 
	params TEXT, 
	PRIMARY KEY (run_id)
);

CREATE TABLE cluster_marker (
	run_id VARCHAR(64) NOT NULL, 
	cluster VARCHAR(32) NOT NULL, 
	gene VARCHAR(128) NOT NULL, 
	rank INTEGER NOT NULL, 
	logfc FLOAT, 
	pval_adj FLOAT, 
	score FLOAT, 
	PRIMARY KEY (run_id, cluster, gene), 
	FOREIGN KEY(run_id) REFERENCES run (run_id) ON DELETE CASCADE
);

CREATE TABLE integration_metric (
	run_id VARCHAR(64) NOT NULL, 
	method VARCHAR(32) NOT NULL, 
	metric VARCHAR(32) NOT NULL, 
	value FLOAT, 
	PRIMARY KEY (run_id, method, metric), 
	FOREIGN KEY(run_id) REFERENCES run (run_id) ON DELETE CASCADE
);

CREATE TABLE sample (
	run_id VARCHAR(64) NOT NULL, 
	sample_id VARCHAR(128) NOT NULL, 
	batch VARCHAR(128) NOT NULL, 
	n_reads BIGINT, 
	pct_pseudoaligned FLOAT, 
	n_barcodes INTEGER, 
	umi_threshold FLOAT, 
	n_cells_called INTEGER, 
	n_removed_low_genes INTEGER, 
	n_removed_high_mito INTEGER, 
	n_removed_doublets INTEGER, 
	n_cells_pass_qc INTEGER, 
	median_umis FLOAT, 
	median_genes FLOAT, 
	median_pct_mito FLOAT, 
	PRIMARY KEY (run_id, sample_id), 
	FOREIGN KEY(run_id) REFERENCES run (run_id) ON DELETE CASCADE
);

CREATE TABLE cell (
	run_id VARCHAR(64) NOT NULL, 
	cell_id VARCHAR(160) NOT NULL, 
	sample_id VARCHAR(128) NOT NULL, 
	n_umis INTEGER, 
	n_genes INTEGER, 
	pct_mito FLOAT, 
	doublet_score FLOAT, 
	marker_label VARCHAR(128), 
	cluster VARCHAR(32), 
	cell_type VARCHAR(128), 
	umap_1 FLOAT, 
	umap_2 FLOAT, 
	PRIMARY KEY (run_id, cell_id), 
	FOREIGN KEY(run_id, sample_id) REFERENCES sample (run_id, sample_id) ON DELETE CASCADE
);

CREATE INDEX ix_cell_sample ON cell (run_id, sample_id);

CREATE INDEX ix_cell_type ON cell (run_id, cell_type);
